import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Datenherkunft","description":"","frontmatter":{"title":"Datenherkunft","covers":{"screens":[],"stories":["US-063","US-064","US-065","US-068"]}},"headers":[],"relativePath":"de/usage/data-lineage.md","filePath":"de/usage/data-lineage.md"}`),a={name:`de/usage/data-lineage.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="datenherkunft" tabindex="-1">Datenherkunft <a class="header-anchor" href="#datenherkunft" aria-label="Permalink to “Datenherkunft”">​</a></h1><p>Die Datenherkunft (Data Lineage) zeigt, wie Daten zwischen Systemen fließen: woher ein Datenobjekt kommt und wohin es geht. Du modellierst sie mit gewöhnlichen Entitäten und Verbindungen und fragst sie über die API ab. Die Seite, die die Herkunft zeichnet, folgt in einem späteren Release; diese Seite behandelt das Modellieren und die Abfrage.</p><p>Du brauchst <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>), um die Herkunft abzufragen und Kataloge zu filtern, und <code>entity:write</code> (Rolle <code>enterprise-architect</code>), um sie zu modellieren. Die Typen kommen mit dem TOGAF-Starterpaket 1.5.0 (siehe <a href="./../administration/metamodel-packages#lineage-types">Lineage-Typen</a>); welche Typen welche Rolle spielen, legt das <a href="./../administration/metamodel-editing#lineage-model">Lineage-Modell</a> fest.</p><h2 id="datenflusse-und-ihre-daten-modellieren" tabindex="-1">Datenflüsse und ihre Daten modellieren <a class="header-anchor" href="#datenflusse-und-ihre-daten-modellieren" aria-label="Permalink to “Datenflüsse und ihre Daten modellieren”">​</a></h2><ol><li>Lege das <em>Data Object</em> an, zum Beispiel <em>Customer Master</em>, und gib ihm optionale Eigenschaften: <em>Data classification</em>, <em>Personal data categories</em> und <em>Data owner</em>.</li><li>Verbinde zwei Systeme durch einen <em>Data Flow</em>, zum Beispiel von <em>SAP ERP</em> nach <em>DWH</em>. Ein Datenfluss läuft zwischen Anwendungskomponenten, Anwendungsdiensten, Technologiekomponenten und Systemsoftware; seine optionalen Eigenschaften sind <em>Protocol</em>, <em>Frequency</em>, <em>Personal data categories</em> und <em>Transformation description</em>.</li><li>Verbinde den Datenfluss mit dem Datenobjekt durch <em>Carries Data</em>. Die Quelle dieser Verbindung ist der <strong>Datenfluss</strong>, nicht ein System: eine Verbindung, die an einer Verbindung beginnt. Ein Fluss kann mehrere Datenobjekte transportieren, und ein Datenobjekt kann von mehreren Flüssen transportiert werden.</li></ol><p>Ein <em>Carries Data</em> von einer Anwendungskomponente wird mit <code>422 SOURCE_NOT_ALLOWED</code> abgelehnt, eines zu einem Datenfluss mit <code>422 TARGET_NOT_ALLOWED</code>. Verbindungen von Verbindungen gehen <strong>eine Ebene tief</strong>: Eine neue Verbindung, deren Quelle oder Ziel selbst eine Verbindung an einer Verbindung ist (zum Beispiel ein <em>Realized By</em> an einem <em>Carries Data</em>), wird mit <code>422 CONNECTION_DEPTH_EXCEEDED</code> abgelehnt, das Quelle oder Ziel nennt. Vorhandene Verbindungen bleiben.</p><p>Aufgaben (Tasks) kommen über die BPMN-Datenassoziationen in die Herkunft: Eine Aufgabe mit einer <em>Data Output Association</em> zu einem Datenobjekt ist ein <strong>Schreiber</strong>, flussaufwärts mit ihrem <em>Transformation type</em>; eine Aufgabe mit einer <em>Data Input Association</em> vom Datenobjekt ist ein <strong>Leser</strong>, flussabwärts.</p><h2 id="die-herkunft-abfragen" tabindex="-1">Die Herkunft abfragen <a class="header-anchor" href="#die-herkunft-abfragen" aria-label="Permalink to “Die Herkunft abfragen”">​</a></h2><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]}&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$OEA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/views/lineage/query&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;startEntityId&quot;: 42, &quot;direction&quot;: &quot;downstream&quot;, &quot;maxDepth&quot;: 50}&#39;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>startEntityId</code></td><td>Pflicht: ein Datenobjekt oder ein System (keine Verbindung)</td></tr><tr><td><code>direction</code></td><td><code>downstream</code> (Verbraucher), <code>upstream</code> (Quellen), <code>both</code> (Standard, die Vereinigung beider Läufe) oder <code>impact</code> (<code>downstream</code> mit <code>impact: true</code> an jedem Knoten)</td></tr><tr><td><code>maxDepth</code></td><td>1 bis 100, Standard 50 (<code>400</code> außerhalb)</td></tr><tr><td><code>metatypeIds</code></td><td>höchstens 50 Entitätstypen (<code>400</code> darüber); behält nur die Knoten dieser Typen und ihrer Untertypen, die Kanten bleiben</td></tr><tr><td><code>dataObjectId</code></td><td>nur für einen Start, der ein System ist: folgt nur den Flüssen, die dieses Datenobjekt transportieren</td></tr></tbody></table><p>Von einem <strong>Datenobjekt</strong> folgt die Abfrage den Flüssen, die es transportieren: <code>downstream</code> von ihren Ursprüngen, <code>upstream</code> von ihren Senken. Von einem <strong>System</strong> folgt sie den Flüssen von oder zu ihm, Schritt für Schritt. Die Antwort listet die <code>nodes</code> (Systeme und Aufgaben, mit <code>depth</code> und <code>roles</code>: origin, intermediate, sink, reader, writer; der Start ist nie ein Knoten), die <code>edges</code> (Datenflüsse, jeweils mit den transportierten Datenobjekten in <code>carriedBy</code>, höchstens 50 mit <code>carriedByTruncated</code>; und die Datenassoziationen der Aufgaben), die <code>paths</code> (höchstens 100) und die Kennzeichen <code>cycleDetected</code> und <code>truncated</code>. Es werden höchstens 5000 Knoten und 10000 Kanten geliefert. Gelöschte Entitäten fehlen.</p><p>Fehler: <code>404</code> für einen unbekannten oder gelöschten Start, <code>422</code> für eine Verbindung als Start, einen unbekannten Entitätstyp im Filter oder eine <code>dataObjectId</code>, die kein Datenobjekt ist, und <code>422 LINEAGE_MODEL_INCOMPLETE</code>, wenn Datenobjekt, Datenfluss oder <em>Carries Data</em> im Lineage-Modell nicht gesetzt ist. Der einzige gelieferte Eigenschaftswert ist der <em>Transformation type</em> einer Datenausgabe, und nur wenn du ihn lesen darfst; sonst hat die Kante <code>transformationRestricted: true</code>.</p><h2 id="datenflusse-mit-personenbezogenen-daten-finden" tabindex="-1">Datenflüsse mit personenbezogenen Daten finden <a class="header-anchor" href="#datenflusse-mit-personenbezogenen-daten-finden" aria-label="Permalink to “Datenflüsse mit personenbezogenen Daten finden”">​</a></h2><p>Lege einen <a href="./catalogs">Katalog</a> von <em>Data Flow</em>-Entitäten an, zeige die Spalten <em>Personal data categories</em> und <em>Protocol</em> und filtere nach <em>Personal data categories ist nicht leer</em> und zum Beispiel <em>Protocol ist JDBC</em>. Ein Filter ohne Treffer zeigt eine leere Tabelle, keinen Fehler. Ein CSV-Export eines Katalogs gehört nicht zu diesem Release.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};